// Standard C Main Signatures
int main(void);
int main(int argc, char *argv[]);

// Return Status Conventions:
// 0: Success (POSIX standard)
// Non-zero: Error/Failure (Status dependent on OS)

// Success Signaling
return 0;

// Failure Signaling Example
return 1;

// OS Agnostic Signaling (Requires <stdlib.h>)
return EXIT_SUCCESS;
return EXIT_FAILURE;

// Implicit Return (C99/C++):
// If control reaches end of main without return,
// 'return 0;' is automatically executed.
int main(void) { /* code */ }
